{"kind": "content", "icon": "🤝", "head": "पाठक और दर्शक की भूमिका", "points": ["अलग अलग स्रोत देखना", "तथ्य और राय में अंतर", "सनसनी से बचना", "ज़िम्मेदारी से साझा करना", "सच के पक्ष में खड़े होना"], "say": "प्रेस की स्वतंत्रता केवल पत्रकारों की ज़िम्मेदारी नहीं, पाठकों और दर्शकों की भी है। हमें अलग अलग स्रोत से खबर देखनी चाहिए। तथ्य और राय में अंतर समझना चाहिए। सनसनीखेज़ खबरों से बचना चाहिए और कुछ भी साझा करने से पहले उसकी सच्चाई जाँचनी चाहिए। जब हम सजग रहते हैं तब प्रेस भी ज़िम्मेदार बनता है।", "ext": 1},
{"kind": "content", "icon": "📚", "head": "कठिन शब्दों का अभ्यास", "points": ["press – प्रेस, समाचार माध्यम", "freedom – स्वतंत्रता", "censorship – सेंसरशिप, खबरों पर रोक", "journalist – पत्रकार", "responsibility – ज़िम्मेदारी"], "say": "इस पाठ के कुछ शब्द याद कीजिए। press का अर्थ है प्रेस या समाचार माध्यम। freedom यानी स्वतंत्रता। censorship का अर्थ है खबरों पर रोक लगाना। journalist यानी पत्रकार। और responsibility का अर्थ है ज़िम्मेदारी। इन शब्दों से अपने वाक्य बनाइए जैसे A free press is the voice of the people यानी स्वतंत्र प्रेस जनता की आवाज़ है।", "ext": 1},
{"kind": "content", "icon": "📝", "head": "परीक्षा के लिए तैयारी", "points": ["निबंध का मुख्य प्रश्न", "प्रेस पर दबाव", "पत्रकार की ज़िम्मेदारी", "डिजिटल युग की चुनौतियाँ", "संदेश"], "say": "इस निबंध से मुख्य प्रश्न, प्रेस पर दबाव, पत्रकार की ज़िम्मेदारी और डिजिटल युग की चुनौतियों पर प्रश्न आते हैं। उत्तर में अंग्रेज़ी के सरल वाक्य प्रयोग कीजिए। दबाव के तीन उदाहरण याद रखिए। अंत में संदेश लिखिए कि स्वतंत्रता और ज़िम्मेदारी साथ चलती हैं।", "ext": 1},
{"kind": "content", "icon": "📰", "head": "समाचार पत्रों का इतिहास भारत में", "points": ["पहला अख़बार 1780 में", "स्वतंत्रता आंदोलन में प्रेस की भूमिका", "गांधी जी के पत्र हरिजन और यंग इंडिया", "आपातकाल में सेंसरशिप", "स्वतंत्र प्रेस की लड़ाई"], "say": "भारत में पहला समाचार पत्र सन सत्रह सौ अस्सी के आसपास निकला। स्वतंत्रता आंदोलन में प्रेस ने बड़ी भूमिका निभाई। गांधी जी ने यंग इंडिया और हरिजन जैसे पत्र निकाले जिनसे उन्होंने लोगों तक अपने विचार पहुँचाए। सन उन्नीस सौ पचहत्तर के आपातकाल में समाचार पत्रों पर सेंसरशिप लगी थी जिसे प्रेस की स्वतंत्रता पर बड़ा आघात माना गया।", "ext": 2},
{"kind": "content", "icon": "🔍", "head": "खोजी पत्रकारिता", "points": ["भ्रष्टाचार का पर्दाफ़ाश", "जनहित में सच सामने लाना", "जोखिम और साहस", "तथ्यों की गहन जाँच", "समाज में सुधार"], "say": "खोजी पत्रकारिता में पत्रकार लंबे समय तक जाँच करके ऐसे सच सामने लाते हैं जिन्हें छुपाने की कोशिश की जा रही हो। इसमें भ्रष्टाचार और अन्याय का पर्दाफ़ाश होता है। यह काम जोखिम भरा है और इसके लिए साहस की ज़रूरत होती है। पर ऐसे काम से समाज में सुधार आता है, इसलिए खोजी पत्रकारिता को पत्रकारिता का सबसे सम्मानित रूप माना जाता है।", "ext": 2},
{"kind": "content", "icon": "⚖️", "head": "स्वतंत्रता बनाम ज़िम्मेदारी", "points": ["झूठी खबर का नुकसान", "किसी की प्रतिष्ठा पर चोट", "भीड़ को भड़काने का खतरा", "संतुलन की ज़रूरत", "आत्म नियमन"], "say": "प्रेस की स्वतंत्रता के साथ ज़िम्मेदारी भी चलनी चाहिए। झूठी खबर से किसी को बड़ा नुकसान हो सकता है। किसी की प्रतिष्ठा पर बेबुनियाद आरोप लग सकता है या भीड़ भड़क सकती है। इसलिए संतुलन ज़रूरी है। कई देशों में मीडिया संस्थाएँ खुद अपने लिए नियम बनाती हैं जिसे आत्म नियमन कहते हैं। इससे विश्वास बना रहता है।", "ext": 2},
{"kind": "content", "icon": "🤔", "head": "अपनी राय बनाइए", "points": ["क्या सब खबरें सच होती हैं", "हम सच कैसे पहचानें", "क्या हर खबर साझा करनी चाहिए", "अख़बार से हम क्या सीख सकते हैं", "एक अनुच्छेद – Role of Press"], "say": "अब इस निबंध पर अपनी राय बनाइए। क्या सब खबरें सच होती हैं। हम सच कैसे पहचान सकते हैं। क्या हर खबर को साझा करना ठीक है। अख़बार पढ़ने से हम क्या सीख सकते हैं। और अंग्रेज़ी में Role of Press विषय पर एक छोटा अनुच्छेद लिखिए। इससे आपकी सोच भी साफ़ होगी और लेखन भी बेहतर बनेगा।", "ext": 2},
{"kind": "content", "icon": "🌐", "head": "अन्य देशों की तुलना", "points": ["कुछ देशों में पूरी स्वतंत्रता", "कुछ में सख़्त नियंत्रण", "पत्रकारों पर खतरा", "अंतर्राष्ट्रीय प्रेस स्वतंत्रता सूचकांक", "भारत की स्थिति और चुनौतियाँ"], "say": "दुनिया के कई देशों में प्रेस को काफ़ी स्वतंत्रता मिलती है जबकि कुछ देशों में सरकार का सख़्त नियंत्रण रहता है। कई जगह पत्रकारों को अपनी जान का भी खतरा रहता है। हर साल अंतर्राष्ट्रीय संस्थाएँ प्रेस की स्वतंत्रता का सूचकांक जारी करती हैं। भारत में प्रेस को अपेक्षाकृत स्वतंत्रता है पर दबाव, विज्ञापन और झूठी खबरों जैसी चुनौतियाँ भी हैं।", "ext": 3},
{"kind": "content", "icon": "🎓", "head": "विद्यार्थी के लिए सीख", "points": ["खबर पढ़ने की आदत", "तथ्य जाँचने की आदत", "अफ़वाह रोकने की ज़िम्मेदारी", "अपनी बात साफ़ रखने का साहस", "सच के साथ खड़े होना"], "say": "इस पाठ से विद्यार्थियों को कई सीख मिलती हैं। रोज़ खबर पढ़ने की आदत डालिए पर तथ्य जाँचना भी सीखिए। अफ़वाहों को आगे फैलाने से रोकना हमारी ज़िम्मेदारी है। अपनी बात साफ़ और सभ्य ढंग से रखने का साहस रखिए। और हमेशा सच के साथ खड़े होइए। यही एक जागरूक नागरिक की पहचान है।", "ext": 3},
{"kind": "content", "icon": "✍️", "head": "निबंध लिखने का ढाँचा – Freedom of Press", "points": ["परिचय – प्रेस और लोकतंत्र", "स्वतंत्रता का अर्थ और महत्त्व", "खतरे और दबाव", "ज़िम्मेदारी और नैतिकता", "निष्कर्ष – संतुलन"], "say": "अगर परीक्षा में स्वतंत्र प्रेस पर निबंध लिखना हो तो पाँच भाग बनाइए। परिचय में प्रेस और लोकतंत्र का संबंध बताइए। दूसरे भाग में स्वतंत्रता का अर्थ और महत्त्व लिखिए। तीसरे में खतरे और दबाव गिनाइए। चौथे में ज़िम्मेदारी और नैतिकता की बात कीजिए। अंत में निष्कर्ष में संतुलन का संदेश दीजिए।", "ext": 3},
{"kind": "content", "icon": "📰", "head": "प्रेस की भूमिका लोकतंत्र में", "points": ["सूचना देना", "जनता की आवाज़ उठाना", "सरकार पर नज़र रखना", "लोकतंत्र का चौथा स्तंभ"], "say": "प्रेस को लोकतंत्र का चौथा स्तंभ कहा जाता है, विधायिका, कार्यपालिका और न्यायपालिका के बाद। उसका काम जनता तक सही सूचना पहुँचाना, सरकार के कामों पर नज़र रखना और जनता की समस्याओं को उठाना है। अगर प्रेस स्वतंत्र न हो, तो लोगों को सच का पता ही नहीं चलेगा और सत्ता मनमानी कर सकती है। इसलिए स्वतंत्र प्रेस को स्वस्थ लोकतंत्र की पहचान माना जाता है।", "ext": 7},
